using System;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;

namespace SearchIndexService
{
    public class TokenValidator
    {
        private readonly byte[] _sharedSecret;
        private static readonly TimeSpan TokenExpiry = TimeSpan.FromMinutes(5);

        public TokenValidator(byte[] sharedSecret)
        {
            _sharedSecret = sharedSecret;
        }

        public bool ValidateServiceToken(string token)
        {
            if (string.IsNullOrEmpty(token)) return false;
            var parts = token.Split('.');
            if (parts.Length != 3) return false;

            var payload = parts[0];
            var timestamp = parts[1];
            var signature = parts[2];

            if (!long.TryParse(timestamp, out var ticks)) return false;
            var tokenTime = new DateTime(ticks, DateTimeKind.Utc);
            if (DateTime.UtcNow - tokenTime > TokenExpiry) return false;

            using var hmac = new HMACSHA256(_sharedSecret);
            var expectedSig = Convert.ToBase64String(
                hmac.ComputeHash(Encoding.UTF8.GetBytes($"{payload}.{timestamp}")));

            return CryptographicOperations.FixedTimeEquals(
                Encoding.UTF8.GetBytes(signature),
                Encoding.UTF8.GetBytes(expectedSig));
        }
    }

    public class QueryNormalizer
    {
        private static readonly Dictionary<string, string> FieldAliases = new()
        {
            ["title"] = "doc_title",
            ["author"] = "doc_author",
            ["content"] = "doc_body",
            ["date"] = "doc_created_at"
        };

        public string NormalizeFieldName(string field)
        {
            var lower = field.ToLowerInvariant().Trim();
            return FieldAliases.TryGetValue(lower, out var mapped) ? mapped : lower;
        }

        public string BuildFilterExpression(string userFilter)
        {
            if (string.IsNullOrWhiteSpace(userFilter)) return string.Empty;
            // Sanitize: only allow alphanumeric, spaces, colons, quotes, parens
            var sanitized = Regex.Replace(userFilter, @"[^\w\s:\"\(\)\-]", "");
            return sanitized;
        }
    }

    public class SearchPattern
    {
        public string FieldName { get; set; }
        public string Pattern { get; set; }
        public bool IsWildcard { get; set; }
    }

    public class PatternCompiler
    {
        private readonly RegexOptions _baseOptions = RegexOptions.IgnoreCase | RegexOptions.Compiled;

        public Regex CompileSearchPattern(SearchPattern pattern)
        {
            string regexStr;
            if (pattern.IsWildcard)
            {
                regexStr = ConvertWildcardToRegex(pattern.Pattern);
            }
            else
            {
                regexStr = BuildPhrasePattern(pattern.Pattern);
            }

            return new Regex(regexStr, _baseOptions, TimeSpan.FromSeconds(5));
        }

        private string ConvertWildcardToRegex(string wildcard)
        {
            var escaped = Regex.Escape(wildcard);
            escaped = escaped.Replace("\\*", ".*").Replace("\\?", ".");
            return $"^{escaped}$";
        }

        private string BuildPhrasePattern(string phrase)
        {
            // Build a pattern that matches the phrase with flexible whitespace
            // and optional surrounding word boundaries
            var words = phrase.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (words.Length == 0) return "(?!)";

            var parts = new List<string>();
            foreach (var word in words)
            {
                // Allow each word to have optional trailing punctuation
                // and flexible inter-word spacing
                parts.Add($"({Regex.Escape(word)}[\\s,;.]*)");
            }

            // Join with flexible separator that allows nested optional groups
            return string.Join("\\s*", parts) + "(?:\\s+|$)*";
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class SearchController : ControllerBase
    {
        private readonly TokenValidator _tokenValidator;
        private readonly QueryNormalizer _normalizer;
        private readonly PatternCompiler _compiler;
        private readonly List<string> _documentStore;

        public SearchController()
        {
            _tokenValidator = new TokenValidator(Encoding.UTF8.GetBytes("service-shared-key-2024"));
            _normalizer = new QueryNormalizer();
            _compiler = new PatternCompiler();
            _documentStore = new List<string>
            {
                "The quick brown fox jumps over the lazy dog",
                "Advanced search indexing with distributed systems",
                "Machine learning approaches to document classification"
            };
        }

        [HttpPost("query")]
        public async Task<IActionResult> ExecuteSearch([FromHeader(Name = "X-Service-Token")] string serviceToken,
                                                       [FromBody] SearchRequest request)
        {
            if (!_tokenValidator.ValidateServiceToken(serviceToken))
                return Unauthorized(new { error = "Invalid service token" });

            if (request == null || string.IsNullOrEmpty(request.Query))
                return BadRequest(new { error = "Query is required" });

            if (request.Query.Length > 500)
                return BadRequest(new { error = "Query too long" });

            var pattern = new SearchPattern
            {
                FieldName = _normalizer.NormalizeFieldName(request.Field ?? "content"),
                Pattern = request.Query,
                IsWildcard = request.UseWildcard
            };

            try
            {
                var compiledRegex = _compiler.CompileSearchPattern(pattern);
                var results = new List<SearchResult>();

                foreach (var doc in _documentStore)
                {
                    var match = compiledRegex.Match(doc);
                    if (match.Success)
                    {
                        results.Add(new SearchResult { Content = doc, Score = 1.0 });
                    }
                }

                return Ok(new { results, count = results.Count });
            }
            catch (RegexMatchTimeoutException)
            {
                return StatusCode(408, new { error = "Search timeout" });
            }
        }
    }

    public class SearchRequest
    {
        public string Query { get; set; }
        public string Field { get; set; }
        public bool UseWildcard { get; set; }
    }

    public class SearchResult
    {
        public string Content { get; set; }
        public double Score { get; set; }
    }
}
